const raw=$json||{};
const object=v=>{if(v&&typeof v==='object'&&!Array.isArray(v))return v;if(typeof v==='string'&&v.length<30000){try{const p=JSON.parse(v);if(p&&typeof p==='object'&&!Array.isArray(p))return p;}catch{}}return null;};
const candidates=[raw,object(raw.query),object(raw.ticket)].filter(Boolean);
const x=candidates.find(v=>typeof v.summary==='string'&&v.summary.trim()&&typeof v.draft_reply==='string'&&v.draft_reply.trim())||raw;
const clean=k=>typeof x[k]==='string'?x[k].trim():'';
const ticket={summary:clean('summary'),priority:clean('priority').toLowerCase(),category:clean('category').toLowerCase(),draft_reply:clean('draft_reply')};
const missing=['summary','draft_reply','priority','category'].filter(k=>!ticket[k]);
const invalid=[];if(ticket.category&&!['refund','delivery','product','other'].includes(ticket.category))invalid.push('category must be refund, delivery, product or other');if(ticket.priority&&!['normal','high'].includes(ticket.priority))invalid.push('priority must be normal or high');
if(missing.length||invalid.length)return [{json:{valid:false,ok:false,error:'missing_or_invalid_ticket_inputs',missing_fields:missing,invalid_fields:invalid,ticket_saved:false,refund_approved:false,customer_email_sent:false,message:'Ticket NOT saved. The helper needs values from the agent. In 03 Agent open create_ticket, choose this published helper, then click the sparkle beside summary, priority, category and draft_reply so ALL FOUR say Defined by agent. Test from 03 Open chat. To test only this helper, use TEST HELPER - fictional sample.',output:'Ticket NOT saved. Missing: '+(missing.join(', ')||'none')+'. '+invalid.join('; ')+' Configure all four create_ticket inputs as Defined by agent, then test from 03 Open chat. For a standalone Sheet check, execute TEST HELPER - fictional sample.'}}];
return [{json:{valid:true,ticket}}];
